local a={}a.BASELINE_PCT=60;a.default="Biodiesel"a.list={{name="Plant Oil",pct=20},{name="Ethanol",pct=200},{name="Biodiesel",pct=60},{name="Sulfurized Diesel",pct=75},{name="Diesel",pct=80},{name="Gasoline",pct=125},{name="Kerosene",pct=150},{name="Turpentine",pct=30}}local b={}for c,d in ipairs(a.list)do b[d.name]=d.pct end;function a.pctOf(e)return b[e]end;function a.scaleFor(e)local f=b[e]if not f or f<=0 then return nil end;return a.BASELINE_PCT/f end;function a.isBad(e)local f=b[e]return f~=nil and f<a.BASELINE_PCT or false end;function a.options()local g={}for h,d in ipairs(a.list)do g[h]={text=d.name.." "..d.pct.."%",value=d.name}end;return g end;a.abbr={["Plant Oil"]="POIL",["Ethanol"]="ETH",["Biodiesel"]="BDSL",["Sulfurized Diesel"]="SDSL",["Diesel"]="DSL",["Gasoline"]="GAS",["Kerosene"]="KERO",["Turpentine"]="TURP"}function a.abbrevOf(e)if e==nil then e=a.default end;return a.abbr[e]or e and e:sub(1,4):upper()or"?"end;return a